"""Complete headache/facial pain with secondary causes and medication overuse."""
from create_headache import rows,q,IC,NG
from qbank_authoring import ref,finalize
TN=ref('EAN Trigeminal Neuralgia Guideline','https://doi.org/10.1111/ene.13950')
II=ref('Idiopathic Intracranial Hypertension Consensus Guidance','https://pmc.ncbi.nlm.nih.gov/articles/PMC6166610/')
SI=ref('Spontaneous Intracranial Hypotension Consensus Guideline','https://pmc.ncbi.nlm.nih.gov/articles/PMC10511987/')
GA=ref('BSR Giant Cell Arteritis Guideline, 2020 Executive Summary','https://academic.oup.com/rheumatology/article/59/3/487/5714025')
OB=ref('ACOG Headaches in Pregnancy and Postpartum Guideline','https://doi.org/10.1097/AOG.0000000000004766')
SA=ref('AHA/ASA Aneurysmal SAH Guideline, 2023','https://doi.org/10.1161/STR.0000000000000436')

q('Continuous strictly unilateral headache has exacerbations with cranial autonomic symptoms and an absolute indomethacin response. Which diagnosis is favored?', 'Hemicrania continua',[
 ('Paroxysmal hemicrania as the best fit despite continuous baseline pain','Paroxysmal hemicrania is defined by discrete short attacks.'),('Typical tension-type headache','Strict unilateral continuous pain with this response pattern suggests another syndrome.'),('Trigeminal neuralgia','The continuous headache baseline differs from brief triggered facial paroxysms.')],
 'The baseline pattern separates related indomethacin-responsive headaches', '**Hemicrania continua is continuous unilateral pain with exacerbations.**', ['Autonomic features or agitation can accompany worsening.','Absolute indomethacin response is part of the classification.'], '**Exclude secondary causes where indicated.**', ['Use a supervised trial with gastrointestinal and renal safety review.','Do not infer the diagnosis from partial nonspecific analgesia alone.'], [['Baseline','Continuous'],['Exacerbations','Autonomic features possible'],['Response','Absolute indomethacin response']], [IC])
q('Very brief unilateral orbital attacks lasting seconds to minutes occur many times daily with conjunctival injection and tearing. Which syndrome is particularly suggested?', 'SUNCT within the short-lasting unilateral neuralgiform headache spectrum',[
 ('Typical migraine without aura','Migraine attacks are much longer.'),('Ordinary tension-type headache','The neuralgiform autonomic pattern is different.'),('Cluster headache as an identical duration syndrome','Typical cluster attacks last 15–180 minutes.')],
 'Duration is central within the trigeminal autonomic differential', '**SUNCT includes both conjunctival injection and lacrimation.**', ['Related SUNA presentations have a different autonomic symptom combination.','Secondary lesions and overlap with trigeminal neuralgia need assessment.'], '**Seek specialist classification and treatment.**', ['Routine slow oral analgesics are poorly matched to brief attacks.','Appropriate imaging is often part of assessment.'], [['SUNCT/SUNA','Seconds to minutes'],['Paroxysmal hemicrania','2–30 minutes'],['Cluster','15–180 minutes']], [IC], 'clinical_scenario')
q('Touching the cheek or brushing teeth triggers seconds-long electric shocks in the right maxillary facial territory. Which diagnosis is most likely?', 'Trigeminal neuralgia',[
 ('Typical migraine','The duration and tactile trigger pattern differ.'),('Cluster headache','Attacks are longer with prominent autonomic features/restlessness.'),('Persistent idiopathic facial pain as the best fit','That is not defined by stereotyped brief triggered shocks.')],
 'A triggerable neuralgiform pain has a specific pattern', '**TN causes severe unilateral paroxysms within trigeminal divisions.**', ['A refractory period can follow an attack.','Sensory deficits or other atypical findings increase concern for secondary disease.'], '**Evaluate the cause, not only the pain.**', ['MRI is recommended in the diagnostic work-up.','MS and structural lesions are important alternatives to classical neurovascular disease.'], [['Quality','Electric/shock-like'],['Duration','Brief paroxysms'],['Trigger','Innocuous facial stimulation']], [IC,TN], 'clinical_scenario')
q('Which medicines are recommended first-choice long-term treatments for trigeminal neuralgia?', 'Carbamazepine or oxcarbazepine',[
 ('Routine opioids as the established preferred option','These are not the first-choice targeted approach.'),('Propranolol as the usual first-line TN drug','This is used for other indications including migraine prevention.'),('Daily antibiotics without an infectious cause','They do not address neuralgic transmission.')],
 'Sodium-channel modulation can suppress neuralgic discharges', '**Carbamazepine and oxcarbazepine are the guideline first choices.**', ['Review sodium, interactions and rash risks as appropriate.','Genetic safety testing is relevant in selected ancestry groups and local protocols.'], '**Consider surgery when appropriate medication is ineffective or poorly tolerated.**', ['Neurovascular anatomy and subtype affect procedural choice.','MRI contact alone is not identical to the full classical TN diagnosis.'], [['Drug class','Sodium-channel modulation'],['Safety','Rash, sodium and interactions'],['Refractory disease','Specialist procedural discussion']], [TN])
q('Headache occurs on 20 days monthly and triptans are used on 12 days monthly for over three months. Which additional diagnosis should be considered?', 'Medication-overuse headache',[
 ('Triptan use cannot contribute until 30 days monthly','The class threshold is lower.'),('Every frequent headache is caused only by overuse','Underlying migraine and other causes can coexist.'),('Medication-overuse headache excludes chronic migraine','Both diagnoses can be recorded when criteria are met.')],
 'Overuse thresholds depend on medication class', '**Triptans, opioids and combination analgesics have a 10-days-per-month overuse threshold.**', ['Simple analgesics such as NSAIDs or paracetamol generally use a 15-day threshold.','The headache and duration criteria also need to be met.'], '**Explain the cycle without blame.**', ['Plan withdrawal and appropriate prevention.','Use a diary and follow-up.'], [['Triptan/opioid/combination','At least 10 days/month'],['Simple analgesic','At least 15 days/month'],['Duration','Over three months']], [IC,NG], 'clinical_scenario')
q('What is the appropriate management principle for medication-overuse headache?', 'A supported withdrawal plan, education, treatment of the underlying headache and follow-up, individualized to the overused drug',[
 ('Replace each overused dose with an opioid indefinitely','This can perpetuate or worsen harm.'),('Treat only with a new scan and ignore medication use','The exposure needs direct management.'),('Abrupt outpatient withdrawal is automatically safe for every dependent opioid user','Dependence and complex cases require a different supervised strategy.')],
 'Withdrawal can initially worsen symptoms before improvement', '**The withdrawal method depends on the drug and clinical complexity.**', ['Explain expected transient worsening and support needs.','Strong opioid overuse and significant comorbidity may warrant specialist or inpatient care.'], '**Reassess after withdrawal.**', ['Prevention can be appropriate for the underlying migraine.','Review relapse risk and a safe acute-use plan.'], [['Education','Explain mechanism and expectations'],['Withdrawal','Drug-specific support'],['Prevention','Treat underlying disorder']], [NG])
q('A patient has a stable typical migraine history, normal neurological examination and no red flags. Is imaging required solely for reassurance?', 'No; routine neuroimaging solely for reassurance is not recommended',[
 ('Yes, every migraine requires annual MRI','This is not routine recommended care.'),('No, therefore new red flags should always be ignored','A changed syndrome requires fresh assessment.'),('Only a scan can diagnose migraine','The diagnosis is usually clinical.')],
 'The investigation should answer a clinical question', '**Typical primary headache without concerning features often needs no imaging.**', ['Incidental findings can create unnecessary uncertainty.','Explain the positive clinical diagnosis.'], '**Provide a safety-net for change.**', ['New focal deficits, papilledema or abrupt onset alter the decision.','Reassess rather than applying an old label automatically.'], [['Stable typical phenotype','Usually clinical diagnosis'],['Reassurance alone','Not an imaging indication'],['New red flag','Re-evaluate']], [NG])
q('A first headache reaches maximum intensity within seconds during exertion. What is the most appropriate initial principle?', 'Urgently evaluate thunderclap headache for SAH and other vascular causes rather than assuming migraine',[
 ('Give a triptan and defer assessment for several weeks','This can miss a life-threatening cause.'),('A normal neurological examination excludes SAH','SAH can present without focal signs.'),('One prior migraine diagnosis makes every new sudden headache benign','A different onset pattern requires reassessment.')],
 'Time to peak is a red flag', '**Thunderclap onset requires an urgent secondary-headache pathway.**', ['Noncontrast CT timing and quality influence sensitivity.','Further testing depends on presentation, timing and the initial findings.'], '**Keep the vascular differential broad.**', ['RCVS, dissection and CVT can also present with severe acute headache.','Do not end assessment solely because the pain improves.'], [['Onset','Seconds to peak'],['First priority','Exclude dangerous secondary causes'],['Normal examination','Not an absolute exclusion']], [SA], 'clinical_scenario')
q('A 74-year-old has new temporal headache, jaw claudication and transient monocular visual loss. What is the best immediate action?', 'Urgent GCA assessment and glucocorticoid treatment without delaying for confirmatory testing when strongly suspected',[
 ('Wait for biopsy before treating sight-threatening disease','Delay can permit irreversible visual loss.'),('Assume normal age-related headache','The ischemic features are concerning.'),('Use a triptan as the only management','This does not treat the vasculitic threat.')],
 'Threatened vision changes the urgency', '**GCA can cause irreversible ischemic visual loss.**', ['Obtain inflammatory markers and arrange an urgent confirmation pathway.','Imaging and/or biopsy strategy depends on local expertise and guidance.'], '**Treat while confirmation proceeds when suspicion is high.**', ['Sight-threatening disease requires urgent ophthalmology and specialist care.','Monitor steroid adverse effects and reassess diagnostic evidence.'], [['Clue','Jaw claudication/visual ischemia'],['Action','Urgent treatment'],['Confirmation','Do not delay vision protection']], [GA], 'clinical_scenario')
q('Papilledema, pulsatile tinnitus and transient visual obscurations occur in a patient with obesity. What is required before concluding idiopathic intracranial hypertension?', 'Exclude structural and venous causes, then assess CSF pressure and composition through an appropriate safe pathway',[
 ('Diagnose IIH from obesity and headache alone','The phenotype is not sufficient.'),('Skip venous imaging because CVT cannot mimic IIH','CVT is an important exclusion.'),('Perform LP before considering a mass lesion','Imaging and procedural safety must come first.')],
 'Idiopathic means relevant secondary causes have been excluded', '**Brain and venous imaging are part of the evaluation of papilledema.**', ['LP opening pressure must be measured appropriately.','A single borderline pressure should not be interpreted in isolation.'], '**Document visual function urgently.**', ['Acuity, fields and disc assessment guide risk.','Headache severity alone does not measure the threat to sight.'], [['Imaging','Structural and venous causes'],['LP','Pressure and CSF composition'],['Vision','Requires direct monitoring']], [II], 'clinical_scenario')
q('What is the central disease-modifying strategy in typical IIH associated with obesity?', 'Sustained weight reduction, alongside vision-directed care and appropriate symptom treatment',[
 ('Repeated LP as a durable universal cure','Serial LP is not the routine long-term solution.'),('Treat headache alone and ignore visual fields','Vision can deteriorate independently of pain.'),('Acetazolamide eliminates the need for weight management','Medication does not replace the disease-modifying strategy.')],
 'Separate disease modification, vision protection and headache care', '**Weight loss can modify the underlying disease in typical obesity-associated IIH.**', ['Acetazolamide can help selected patients, particularly with visual involvement.','Rapidly declining vision needs urgent surgical consideration.'], '**Monitor objective visual outcomes.**', ['Tailor weight interventions to severity and feasibility.','Avoid assuming headache improvement proves papilledema resolution.'], [['Weight reduction','Disease modification'],['Acetazolamide','Selected pressure/vision benefit'],['Threatened sight','Urgent specialist escalation']], [II])
q('Headache is substantially worse upright and improves on lying down. Brain MRI shows smooth pachymeningeal enhancement and brain sag. Which diagnosis is favored?', 'Spontaneous intracranial hypotension from a spinal CSF leak or related fistula',[
 ('IIH as the only interpretation','The orthostatic pattern and imaging favor a low-CSF-volume syndrome.'),('A normal LP pressure would exclude SIH','Opening pressure can be normal.'),('All postural headache is benign dehydration','The neurological imaging pattern needs specialist assessment.')],
 'CSF volume loss can alter intracranial support', '**Orthostatic headache is an important SIH clue.**', ['MRI brain and spine form part of the evaluation.','Normal imaging or pressure does not invariably exclude the disorder.'], '**Use a specialist leak pathway.**', ['Non-targeted epidural blood patch is an early treatment option in appropriate cases.','Persistent disease may need leak-localizing myelography and targeted treatment.'], [['Symptom','Orthostatic headache'],['MRI','Pachymeningeal enhancement/brain sag'],['Pressure','May be normal']], [SI], 'clinical_scenario')
q('Which change most strongly argues for reassessing an established primary-headache diagnosis?', 'New papilledema, focal neurological deficit, systemic illness or a major change in onset and pattern',[
 ('A familiar recurrent attack with an unchanged normal examination','That may fit the established disorder.'),('A stable family history of migraine alone','This is not itself a new secondary-cause red flag.'),('A typical reversible aura recurring unchanged for years','The longstanding stable pattern is less concerning than new atypical features.')],
 'A previous diagnosis does not explain every future headache', '**Red flags are a reason to revisit the differential.**', ['Cancer, immune compromise, positional features and exertional onset can alter risk.','The investigation depends on the suspected cause.'], '**Ask about the exact change.**', ['Compare with the patient’s usual attack.','Provide clear safety-net advice rather than indiscriminate reassurance or imaging.'], [['Pattern change','Reassess'],['Objective abnormality','Investigate'],['Stable typical headache','Different pathway']], [NG])
q('A woman five days postpartum has a new severe headache and elevated blood pressure. What is the most appropriate approach?', 'Urgent evaluation for preeclampsia and other secondary postpartum causes, not automatic attribution to migraine or dural puncture',[
 ('Delivery excludes preeclampsia','The disorder can present postpartum.'),('Any prior epidural proves the headache is only low pressure','CVT, hypertensive disease and other causes can coexist or mimic it.'),('A migraine history removes the need to check BP and neurological signs','New postpartum headache requires its own assessment.')],
 'Pregnancy and postpartum status change the differential', '**Hypertensive disease, CVT, RCVS and other serious disorders require consideration.**', ['Assess BP, examination, systemic symptoms and procedural history.','Imaging and obstetric treatment depend on findings.'], '**Treat the identified emergency promptly.**', ['A postural component alone does not eliminate other causes.','Coordinate obstetric, neurological and anesthetic expertise as needed.'], [['Postpartum headache','Secondary causes matter'],['Elevated BP','Preeclampsia assessment'],['Prior epidural','One clue, not a complete diagnosis']], [OB], 'clinical_scenario')

if __name__=='__main__':finalize('Neurology',11,'Headache and Facial Pain','neuro-headache',rows,28)
